    adj = {i: [] for i in range(numCourses)}
    for crs, pre in prerequisites:
        adj[crs].append(pre)
    visited = set()
    def dfs(crs):
        if crs in visited: return False
        if adj[crs] == []: return True
        visited.add(crs)
        for pre in adj[crs]:
            if not dfs(pre): return False
