class MyQueue:
    def __init__(self):
        self.s1 = []
        self.s2 = []
    def push(self, x: int) -> None:
        self.s1.append(x)
    def pop(self) -> int:
        self.peek()
        return self.s2.pop()
    def peek(self) -> int:
        if not self.s2:
